  function(request, sender, sendResponse) {
    if (request.action === "fetchAmazonData") {
      const amazonProductId = request.productId;

      // Replace this with your actual Amazon API call or scraping logic
      fetch(`https://api.amazon.com/product/dp/${amazonProductId}`) // Example using the API
        .then(response => response.json())
        .then(data => {
          sendResponse({ data: data });
        })
        .catch(error => {
          console.error("Error fetching Amazon data:", error);
          sendResponse({ error: error });
        });
      return true; // Indicate that you will send a response asynchronously
    }
  }
);
```

